export function createCache(load) {
  const entries = new Map();
  return async function get(key) {
    if (entries.has(key)) return entries.get(key);
    // new Promise converts synchronous throws from load into rejections.
    const promise = new Promise((resolve) => resolve(load(key)));
    entries.set(key, promise);
    promise.catch(() => {
      if (entries.get(key) === promise) entries.delete(key);
    });
    return promise;
  };
}
EOF
cat > regression.test.mjs <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createCache } from './src.mjs';

test('concurrent callers share one in-flight load', async () => {
  let calls = 0;
  const get = createCache(async (k) => { calls++; await new Promise((r) => setTimeout(r, 5)); return k + calls; });
  const [a, b] = await Promise.all([get('x'), get('x')]);
  assert.equal(a, 'x1'); assert.equal(b, 'x1'); assert.equal(calls, 1);
});

test('undefined values are cached', async () => {
  let calls = 0;
  const get = createCache(async () => { calls++; return undefined; });
  assert.equal(await get('x'), undefined);
  assert.equal(await get('x'), undefined);
  assert.equal(calls, 1);
});

test('rejected loads are evicted and retried, concurrent callers share rejection', async () => {
  let calls = 0;
  const get = createCache(async () => { calls++; if (calls === 1) throw new Error('boom'); return 'ok'; });
  const results = await Promise.allSettled([get('x'), get('x')]);
  assert.deepEqual(results.map((r) => r.status), ['rejected', 'rejected']);
  assert.equal(calls, 1);
  assert.equal(await get('x'), 'ok');
  assert.equal(calls, 2);
});

test('synchronous throws become rejections and allow retry', async () => {
  let calls = 0;
  const get = createCache((k) => { calls++; if (calls === 1) throw new Error('sync'); return k; });
  const p = get('x');
  assert.ok(p instanceof Promise);
  await assert.rejects(p, /sync/);
  assert.equal(await get('x'), 'x');
});

test('different keys are independent', async () => {
  const get = createCache(async (k) => { if (k === 'bad') throw new Error('bad'); return k; });
  await assert.rejects(get('bad'));
  assert.equal(await get('good'), 'good');
  assert.equal(await get('other'), 'other');
});
EOF
