+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { createCache } from './src.mjs';
+
+test('concurrent calls share a load and cache undefined', async () => {
+  let calls = 0;
+  let resolve;
+  const get = createCache(() => {
+    calls++;
+    return new Promise(done => { resolve = done; });
+  });
+  const first = get('x');
+  const second = get('x');
+  await Promise.resolve();
+  assert.equal(calls, 1);
+  resolve(undefined);
+  assert.deepEqual(await Promise.all([first, second]), [undefined, undefined]);
+  assert.equal(await get('x'), undefined);
+  assert.equal(calls, 1);
+});
+
+for (const synchronous of [false, true]) {
+  test(`${synchronous ? 'synchronous throws' : 'rejected loads'} are shared and retried`, async () => {
+    const error = new Error('failed');
+    let calls = 0;
+    const get = createCache(() => {
+      if (++calls > 1) return 'recovered';
+      if (synchronous) throw error;
+      return Promise.reject(error);
+    });
+    const first = get('x');
+    const second = get('x');
+    const results = await Promise.allSettled([first, second]);
+    assert.deepEqual(results, [
+      { status: 'rejected', reason: error },
+      { status: 'rejected', reason: error },
+    ]);
+    assert.equal(calls, 1);
+    assert.equal(await get('x'), 'recovered');
+    assert.equal(await get('x'), 'recovered');
+    assert.equal(calls, 2);
+  });
+}
+
+test('different keys load independently', async () => {
+  let resolve;
+  const calls = [];
+  const get = createCache(key => {
+    calls.push(key);
+    return key === 'slow' ? new Promise(done => { resolve = done; }) : key;
+  });
+  const slow = get('slow');
+  assert.equal(await get('fast'), 'fast');
+  assert.deepEqual(calls, ['slow', 'fast']);
+  resolve('done');
+  assert.equal(await slow, 'done');
+});
